import{_ as p,a0 as o,w as r,s as d,ao as l,I as a,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"五條強化 SSH 安全的建議 | LCTT x X-CMD","titleTemplate":false,"description":"五條強化 SSH 安全的建議 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五條強化 SSH 安全的建議 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五條強化 SSH 安全的建議 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160620 5 SSH Hardening Tips","title":"五條強化 SSH 安全的建議","tag":"201608","desc":""},"relativePath":"201608/20160620 5 SSH Hardening Tips.md","filePath":"[post].md"}'),h={name:"201608/20160620 5 SSH Hardening Tips.md"};function u(g,s,k,b,m,c){const n=o("Link");return r(),d("div",null,[s[25]||(s[25]=l('<h1 id="五條強化-ssh-安全的建議" tabindex="-1">五條強化 SSH 安全的建議 <a class="header-anchor" href="#五條強化-ssh-安全的建議" aria-label="Permalink to “五條強化 SSH 安全的建議”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/binary-1188510_1920_0.jpg?itok=ocPCL_9G" alt=""></p><p><em>採用這些簡單的建議，使你的 OpenSSH 會話更加安全。</em></p><p>當你查看你的 SSH 服務日誌，可能你會發現充斥着一些不懷好意的嘗試性登錄。這裏有 5 條常規建議（和一些個別特殊策略）可以讓你的 OpenSSH 會話更加安全。</p><h3 id="_1-強化密碼登錄" tabindex="-1">1. 強化密碼登錄 <a class="header-anchor" href="#_1-強化密碼登錄" aria-label="Permalink to “1. 強化密碼登錄”">​</a></h3><p>密碼登錄很方便，因為你可以從任何地方的任何機器上登錄。但是它們在暴力攻擊面前也是脆弱的。嘗試以下策略來強化你的密碼登錄。</p>',6)),a("ul",null,[s[6]||(s[6]=a("li",null,[e("使用一個密碼生成工具，例如 pwgen。pwgen 有幾個選項，最有用的就是密碼長度的選項（例如，"),a("code",null,"pwgen 12"),e(" 產生一個12位字符的密碼）")],-1)),a("li",null,[s[1]||(s[1]=e("不要重複使用密碼。忽略所有那些不要寫下你的密碼的建議，然後將你的所有登錄信息都記在一個本子上。如果你不相信我的建議，那總可以相信安全權威 ",-1)),i(n,{href:"https://www.schneier.com/blog/archives/2005/06/write_down_your.html"},{default:t(()=>[...s[0]||(s[0]=[e("Bruce Schneier",-1)])]),_:1}),s[2]||(s[2]=e(" 吧。如果你足夠細心，沒有人能夠發現你的筆記本，那麼這樣能夠不受到網絡上的那些攻擊。",-1))]),s[7]||(s[7]=a("li",null,[e("你可以為你的登錄記事本增加一些額外的保護措施，例如用字符替換或者增加新的字符來掩蓋筆記本上的登錄密碼。使用一個簡單而且好記的規則，比如説給你的密碼增加兩個額外的隨機字符，或者使用單個簡單的字符替換，例如 "),a("code",null,"#"),e(" 替換成 "),a("code",null,"*"),e("。")],-1)),s[8]||(s[8]=a("li",null,"為你的 SSH 服務開啓一個非默認的監聽端口。是的，這是很老套的建議，但是它確實很有效。檢查你的登錄；很有可能 22 端口是被普遍攻擊的端口，其他端口則很少被攻擊。",-1)),a("li",null,[s[4]||(s[4]=e("使用 ",-1)),i(n,{href:"http://www.fail2ban.org/wiki/index.php/Main_Page"},{default:t(()=>[...s[3]||(s[3]=[e("Fail2ban",-1)])]),_:1}),s[5]||(s[5]=e(" 來動態保護你的服務器，是服務器免於被暴力攻擊。",-1))]),s[9]||(s[9]=a("li",null,"使用不常用的用户名。絕不能讓 root 可以遠程登錄，並避免用户名為“admin”。",-1))]),s[26]||(s[26]=l(`<h3 id="_2-解決-too-many-authentication-failures-報錯" tabindex="-1">2. 解決 <code>Too Many Authentication Failures</code> 報錯 <a class="header-anchor" href="#_2-解決-too-many-authentication-failures-報錯" aria-label="Permalink to “2. 解決 Too Many Authentication Failures 報錯”">​</a></h3><p>當我的 ssh 登錄失敗，並顯示“Too many authentication failures for carla”的報錯信息時，我很難過。我知道我應該不介意，但是這報錯確實很礙眼。而且，正如我聰慧的奶奶曾經説過，傷痛之感並不能解決問題。解決辦法就是在你的（客户端的） <code>~/.ssh/config</code> 文件設置強制密碼登錄。如果這個文件不存在，首先創個 <code>~/.ssh/</code> 目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/.ssh</span></span>
<span class="line"><span>$ chmod 700 ~/.ssh</span></span></code></pre></div><p>然後在一個文本編輯器創建 <code>~/.ssh/confg</code> 文件，輸入以下行，使用你自己的遠程域名替換 HostName。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HostName remote.site.com</span></span>
<span class="line"><span>PubkeyAuthentication=no</span></span></code></pre></div><p>（LCTT 譯註：這種錯誤發生在你使用一台 Linux 機器使用 ssh 登錄另外一台服務器時，你的 .ssh 目錄中存儲了過多的私鑰文件，而 ssh 客户端在你沒有指定 -i 選項時，會默認逐一嘗試使用這些私鑰來登錄遠程服務器後才會提示密碼登錄，如果這些私鑰並不能匹配遠程主機，顯然會觸發這樣的報錯，甚至拒絕連接。因此本條是通過禁用本地私鑰的方式來強制使用密碼登錄——顯然這並不可取，如果你確實要避免用私鑰登錄，那你應該用 <code>-o PubkeyAuthentication=no</code> 選項登錄。顯然這條和下兩條是互相矛盾的，所以請無視本條即可。）</p><h3 id="_3-使用公鑰認證" tabindex="-1">3. 使用公鑰認證 <a class="header-anchor" href="#_3-使用公鑰認證" aria-label="Permalink to “3. 使用公鑰認證”">​</a></h3><p>公鑰認證比密碼登錄安全多了，因為它不受暴力密碼攻擊的影響，但是並不方便因為它依賴於 RSA 密鑰對。首先，你要創建一個公鑰/私鑰對。下一步，私鑰放於你的客户端電腦，並且複製公鑰到你想登錄的遠程服務器。你只能從擁有私鑰的電腦登錄才能登錄到遠程服務器。你的私鑰就和你的家門鑰匙一樣敏感；任何人獲取到了私鑰就可以獲取你的賬號。你可以給你的私鑰加上密碼來增加一些強化保護規則。</p><p>使用 RSA 密鑰對管理多個用户是一種好的方法。當一個用户離開了，只要從服務器刪了他的公鑰就能取消他的登錄。</p><p>以下例子創建一個新的 3072 位長度的密鑰對，它比默認的 2048 位更安全，而且為它起一個獨一無二的名字，這樣你就可以知道它屬於哪個服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-keygen -t rsa -b 3072 -f id_mailserver</span></span></code></pre></div><p>以下創建兩個新的密鑰, <code>id_mailserver</code> 和 <code>id_mailserver.pub</code>，<code>id_mailserver</code> 是你的私鑰--不要傳播它！現在用 <code>ssh-copy-id</code> 命令安全地複製你的公鑰到你的遠程服務器。你必須確保在遠程服務器上有可用的 SSH 登錄方式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-copy-id -i  id_rsa.pub user@remoteserver</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/bin/ssh-copy-id: INFO: attempting to log in with the new key(s), to filter out any that are already installed</span></span>
<span class="line"><span>user@remoteserver&#39;s password:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number of key(s) added: 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Now try logging into the machine, with:   &quot;ssh &#39;user@remoteserver&#39;&quot;</span></span>
<span class="line"><span>and check to make sure that only the key(s) you wanted were added.</span></span></code></pre></div><p><code>ssh-copy-id</code> 會確保你不會無意間複製了你的私鑰。從上述輸出中複製登錄命令，記得帶上其中的單引號，以測試你的新的密鑰登錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh &#39;user@remoteserver&#39;</span></span></code></pre></div><p>它將用你的新密鑰登錄，如果你為你的私鑰設置了密碼，它會提示你輸入。</p><h3 id="_4-取消密碼登錄" tabindex="-1">4. 取消密碼登錄 <a class="header-anchor" href="#_4-取消密碼登錄" aria-label="Permalink to “4. 取消密碼登錄”">​</a></h3><p>一旦你已經測試並且驗證了你的公鑰可以登錄，就可以取消密碼登錄，這樣你的遠程服務器就不會被暴力密碼攻擊。如下設置<strong>你的遠程服務器</strong>的 <code>/etc/sshd_config</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PasswordAuthentication no</span></span></code></pre></div><p>然後重啓服務器上的 SSH 守護進程。</p><h3 id="_5-設置別名-這很快捷而且很有-b-格" tabindex="-1">5. 設置別名 -- 這很快捷而且很有 B 格 <a class="header-anchor" href="#_5-設置別名-這很快捷而且很有-b-格" aria-label="Permalink to “5. 設置別名 -- 這很快捷而且很有 B 格”">​</a></h3><p>你可以為你的遠程登錄設置常用的別名，來替代登錄時輸入的命令，例如 <code>ssh -u username -p 2222 remote.site.with.long-name</code>。你可以使用 <code>ssh remote1</code>。你的客户端機器上的 <code>~/.ssh/config</code> 文件可以參照如下設置</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host remote1</span></span>
<span class="line"><span>HostName remote.site.with.long-name</span></span>
<span class="line"><span>Port 2222</span></span>
<span class="line"><span>User username</span></span>
<span class="line"><span>PubkeyAuthentication no</span></span></code></pre></div><p>如果你正在使用公鑰登錄，可以參照這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host remote1</span></span>
<span class="line"><span>HostName remote.site.with.long-name</span></span>
<span class="line"><span>Port 2222</span></span>
<span class="line"><span>User username</span></span>
<span class="line"><span>IdentityFile  ~/.ssh/id_remoteserver</span></span></code></pre></div>`,25)),a("p",null,[i(n,{href:"http://www.openssh.com/"},{default:t(()=>[...s[10]||(s[10]=[e("OpenSSH 文檔",-1)])]),_:1}),s[11]||(s[11]=e(" 很長而且詳細，但是當你掌握了基礎的 SSH 使用規則之後，你會發現它非常的有用，而且包含很多可以通過 OpenSSH 來實現的炫酷效果。",-1))]),s[27]||(s[27]=a("hr",null,null,-1)),a("p",null,[s[13]||(s[13]=e("via: ",-1)),i(n,{href:"https://www.linux.com/learn/5-ssh-hardening-tips"},{default:t(()=>[...s[12]||(s[12]=[e("https://www.linux.com/learn/5-ssh-hardening-tips",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=e("作者：",-1)),i(n,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[14]||(s[14]=[e("CARLA SCHRODER",-1)])]),_:1}),s[18]||(s[18]=e(" 譯者：",-1)),i(n,{href:"https://github.com/maywanting"},{default:t(()=>[...s[15]||(s[15]=[e("maywanting",-1)])]),_:1}),s[19]||(s[19]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[20]||(s[20]=[e("LCTT",-1)])]),_:1}),s[23]||(s[23]=e(" 原創翻譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[21]||(s[21]=[e("Linux中國",-1)])]),_:1}),s[24]||(s[24]=e(" 榮譽推出",-1))])])}const w=p(h,[["render",u]]);export{S as __pageData,w as default};
